<?php require_once 'includes.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(404);page_header('Trip not found');echo '<div class="page-wrap"><h1>Trip not found</h1></div>';page_footer();exit;}$s=db()->prepare('SELECT t.*,u.name host_name FROM trips t JOIN users u ON u.id=t.host_id WHERE t.id=?');$s->execute([$id]);$t=$s->fetch();if(!$t){http_response_code(404);page_header('Trip not found');echo '<div class="page-wrap"><h1>Trip not found</h1></div>';page_footer();exit;}$errors=[];$success='';if($_SERVER['REQUEST_METHOD']==='POST'){require_login();verify_csrf();if((int)$t['host_id']===(int)$_SESSION['user_id'])$errors[]='You cannot request your own trip.';elseif($t['status']!=='open'||(int)$t['seats_available']<1)$errors[]='No seats are available.';else{$msg=trim((string)($_POST['message']??''));$seats=filter_var($_POST['seats']??1,FILTER_VALIDATE_INT);if(!$seats||$seats<1||$seats>(int)$t['seats_available'])$errors[]='Choose a valid number of seats.';if(strlen($msg)>500)$errors[]='Message must be 500 characters or fewer.';if(!$errors){try{$s=db()->prepare('INSERT INTO trip_requests(trip_id,requester_id,seats_requested,message) VALUES(?,?,?,?)');$s->execute([$id,$_SESSION['user_id'],$seats,$msg?:null]);$success='Request sent. The host can review it from their profile.';}catch(PDOException $x){$errors[]=$x->getCode()==='23000'?'You have already requested this trip.':'Unable to submit request.';}}}}page_header($t['title']);?><section class="page-intro"><p class="eyebrow"><?=$t['trip_type']==='carpool'?'SHARED CAR RIDE':'SHARED GROUP TRIP'?></p><h1><?=e($t['title'])?></h1><p><?=e($t['from_city'])?> → <?=e($t['to_place'])?> · <?=e(date('d M Y',strtotime($t['travel_date'])))?></p></section><div class="page-wrap profile-grid"><section class="panel"><h2>Journey details</h2><p><strong>From:</strong> <?=e($t['from_city'])?></p><p><strong>Destination:</strong> <?=e($t['to_place'])?></p><p><strong>Date:</strong> <?=e(date('l, d F Y',strtotime($t['travel_date'])))?></p><p><strong>Duration:</strong> <?= (int)$t['duration_days']?> day(s)</p><p><strong>Host:</strong> <?=e($t['host_name'])?></p><?php if($t['trip_type']==='carpool'):?><p><strong>Vehicle:</strong> <?=e($t['vehicle']?:'To be confirmed')?></p><p><strong>Luggage:</strong> <?=e($t['luggage_notes']?:'Ask host')?></p><?php endif;?><h3>About this trip</h3><p><?=nl2br(e($t['description']?:'No description provided.'))?></p><div class="safety-note">Use a public meeting point and verify details independently before travelling.</div></section><aside class="panel"><p class="eyebrow">ESTIMATED CONTRIBUTION</p><div class="price" style="font-size:2rem">₹<?=number_format((float)$t['estimated_cost'])?></div><p>per person · <?= (int)$t['seats_available']?> seats left</p><?php if($success):?><div class="success-note"><?=e($success)?></div><?php endif;?><?php if($errors):?><div class="error-list"><ul><?php foreach($errors as $x):?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif;?><?php if((int)$t['host_id']===(int)($_SESSION['user_id']??0)):?><a class="btn btn-primary full-width" href="profile.php">Manage in profile</a><?php elseif($t['status']!=='open'||(int)$t['seats_available']<1):?><p>Not accepting requests right now.</p><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label class="form-field">Seats requested<select name="seats"><?php for($i=1;$i<=min(8,(int)$t['seats_available']);$i++):?><option><?=$i?></option><?php endfor;?></select></label><label class="form-field">Message to host<textarea name="message" maxlength="500" placeholder="Introduce yourself or ask a question"></textarea></label><button class="btn btn-primary full-width">Request to join</button></form><?php endif;?></aside></div><?php page_footer();?>